@Composable
fun AppNavHost(navController: NavHostController) {
    NavHost(navController, startDestination = "home") {
        composable("home") { HomeScreen(navController) }
        composable("details/{id}") { DetailsScreen(navController) }
    } // one Activity, one NavHost, shared ViewModel scope available across all destinations
}

@Composable
fun AppNavigation() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = "home"
    ) {
        composable("home") {
            HomeScreen(onDetail = { id ->
                navController.navigate("detail/$id")
            })
        }
        composable("detail/{id}") { backStackEntry ->
            val id = backStackEntry.arguments?.getString("id")
            DetailScreen(id = id)
        }
    }
}

// Avoid duplicate destinations
navController.navigate("home") {
    launchSingleTop = true
}

// Clear back stack up to a destination
navController.navigate("home") {
    popUpTo("login") { inclusive = true }
    launchSingleTop = true
}

// Pop back
navController.popBackStack()

@Serializable data object Home
@Serializable data class Detail(val id: Int)

NavHost(
    navController = navController,
    startDestination = Home
) {
    composable<Home> {
        HomeScreen(
            onItemClick = { id ->
                navController.navigate(Detail(id))
            }
        )
    }
    composable<Detail> { backStackEntry ->
        val detail: Detail = backStackEntry.toRoute()
        DetailScreen(id = detail.id)
    }
}
